<script setup>import AppShell from'../Layouts/AppShell.vue';import{Head,useForm}from'@inertiajs/vue3';defineProps({step:String,user:Object});const role=useForm({role:'photographer'}),profile=useForm({first_name:'',last_name:'',company_name:'',email:''});</script><template><AppShell><Head title="Onboarding"/><div class="mx-auto max-w-2xl"><p class="eyebrow">Studio setup</p><h1 class="mt-2 font-display text-3xl font-bold">Shape your LensPic workspace</h1><div class="panel mt-8 p-7"><template v-if="step==='role'"><h2 class="font-display text-xl font-bold">How will you use LensPic?</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><button v-for="r in ['photographer','user']" :key="r" :class="['rounded-2xl border p-6 text-left',role.role===r?'border-indigo bg-indigo/5':'border-black/10']" @click="role.role=r"><b class="capitalize">{{r}}</b><p class="mt-2 text-sm text-black/45">{{r==='photographer'?'Create events and deliver galleries.':'Join events and discover your photos.'}}</p></button></div><button class="btn-primary mt-6" @click="role.post('/onboarding/account-type')">Continue</button></template><template v-else><h2 class="font-display text-xl font-bold">Complete your studio profile</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><input v-model="profile.first_name" class="field" placeholder="First name"><input v-model="profile.last_name" class="field" placeholder="Last name"></div><input v-model="profile.company_name" class="field mt-4" placeholder="Studio name"><input v-model="profile.email" class="field mt-4" type="email" placeholder="Studio email"><button class="btn-primary mt-6" @click="profile.post('/onboarding/profile')">Finish setup</button></template></div></div></AppShell></template>
